const CURRENCY_COUNTRIES = {
  EUR:'EU',USD:'US',GBP:'GB',CHF:'CH',CZK:'CZ',PLN:'PL',HUF:'HU',SEK:'SE',NOK:'NO',DKK:'DK',
  RON:'RO',HRK:'HR',BGN:'BG',RSD:'RS',TRY:'TR',UAH:'UA',RUB:'RU',THB:'TH',JPY:'JP',CNY:'CN',
  KRW:'KR',AUD:'AU',NZD:'NZ',CAD:'CA',MXN:'MX',BRL:'BR',ARS:'AR',CLP:'CL',AED:'AE',SAR:'SA',
  QAR:'QA',KWD:'KW',BHD:'BH',OMR:'OM',JOD:'JO',ILS:'IL',EGP:'EG',IDR:'ID',INR:'IN',PKR:'PK',
  BDT:'BD',LKR:'LK',NPR:'NP',MYR:'MY',SGD:'SG',PHP:'PH',VND:'VN',HKD:'HK',TWD:'TW',ZAR:'ZA',
  MAD:'MA',TND:'TN',GEL:'GE',AMD:'AM',AZN:'AZ',KZT:'KZ',UZS:'UZ'
};
function currencyFlag(code) {
  const country = CURRENCY_COUNTRIES[code];
  return country ? String.fromCodePoint(...[...country].map(letter => 127397 + letter.charCodeAt(0))) : '💱';
}
function currencyOptionLabel(currency) {
  // 1.0.23: название валюты на языке приложения (Intl), английское — запасной вариант
  let name = currency.name;
  try { name = new Intl.DisplayNames([getLang()], { type: 'currency' }).of(currency.code) || name; } catch (_) {}
  return currencyFlag(currency.code) + ' ' + currency.code + ' · ' + name;
}
const RATE_SOURCE_ECB = { ru:'ЕЦБ', en:'ECB', de:'EZB', es:'BCE', fr:'BCE', pt:'BCE', it:'BCE', pl:'EBC', el:'ΕΚΤ', tr:'AMB' };
function rateSourceName(src) {
  const ecb = RATE_SOURCE_ECB[getLang()] || 'ECB';
  return String(src || '').replace(/\bECB\b/g, ecb).replace(' via Frankfurter', ' · Frankfurter');
}
function fmtRateDate(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso || '')) return iso || '';
  try { return new Intl.DateTimeFormat(getLang(), { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'UTC' }).format(new Date(iso + 'T00:00:00Z')); } catch (_) { return iso; }
}

function detectInitialLang() {
  try {
    const saved = localStorage.getItem('sw_lang');
    if (saved && TRANSLATIONS[saved]) return saved;
    // старые установки без sw_lang видели русский — не переключаем их
    if (localStorage.getItem('sw_last') || localStorage.getItem('sw_onboarding_prefs_done')) return 'ru';
    const list = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ''];
    for (const l of list) {
      const c = String(l).toLowerCase().slice(0, 2);
      if (TRANSLATIONS[c]) { localStorage.setItem('sw_lang', c); return c; }
    }
    localStorage.setItem('sw_lang', 'en');
  } catch (e) {}
  return 'en';
}
let _lang = detectInitialLang();
let _currency = null;

function t(key) {
  const dict = TRANSLATIONS[_lang] || TRANSLATIONS['ru'];
  return dict[key] ?? TRANSLATIONS['ru'][key] ?? key;
}

function setLang(lang) {
  if (!TRANSLATIONS[lang]) return;
  _lang = lang;
  localStorage.setItem('sw_lang', lang);
  applyTranslations();
  // 1.0.22: перерисовываем шапку, списки и модальные формы на новом языке
  try { if (typeof S !== 'undefined' && S.trip && typeof renderAll === 'function') renderAll(); } catch (e) { console.warn('[i18n] rerender failed', e); }
}

function getLang() { return _lang; }

function setCurrency(code) {
  if (!CURRENCIES.some(currency => currency.code === code)) return;
  _currency = code;
}

function getCurrency() { return _currency || 'EUR'; }

function getCurrencySymbol(code) {
  const c = code || getCurrency();
  return CURRENCIES.find(x => x.code === c)?.symbol || c;
}

function applyTranslations() {
  try {
    const sfx = _lang === 'ru' ? '' : (_lang === 'de' ? '.de' : '.en');
    document.querySelectorAll('a[data-legal]').forEach(a => a.setAttribute('href', '/' + a.dataset.legal + sfx + '.html'));
  } catch (e) {}
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const attr = el.getAttribute('data-i18n-attr');
    const asHtml = el.hasAttribute('data-i18n-html');
    const val = t(key);
    if (attr) {
      el.setAttribute(attr, val);
    } else if (asHtml) {
      el.innerHTML = val;
    } else {
      el.textContent = val;
    }
  });
  // Update html lang attribute
  document.documentElement.lang = _lang;
}
